import {Config, Field} from 'alinea'

export default Config.type('Select field', {
  fields: {
    category: Field.select('Category', {
      options: {
        news: 'News',
        release: 'Release notes',
        tutorial: 'Tutorial'
      }
    }),
    alignment: Field.select('Alignment', {
      initialValue: 'left',
      options: {
        left: 'Left',
        center: 'Center',
        right: 'Right'
      }
    }),
    tags: Field.select.multiple('Tags', {
      options: {
        design: 'Design',
        development: 'Development',
        marketing: 'Marketing'
      }
    })
  }
})

import {Config, Field} from 'alinea'

export const categories = {
  news: 'News',
  release: 'Release notes',
  tutorial: 'Tutorial'
}

export const Post = Config.document('Post', {
  fields: {
    category: Field.select('Category', {options: categories}),
    tags: Field.select.multiple('Tags', {
      options: {design: 'Design', development: 'Development'}
    })
  }
})

export function categoryLabel(key: keyof typeof categories | null) {
  return key ? categories[key] : ''
}

import {cms} from '@/cms'
import {BlogPost} from '@/schema'

const releases = await cms.find({
  type: BlogPost,
  filter: {tags: {includes: 'release'}}
})
